using System;using System.IO;using System.Reflection;using System.Linq;using UnityEditor.SceneManagement;using UnityEngine;
public static class VerifyFirstRoomEffects {
 static void Require(bool b,string m){if(!b)throw new Exception(m);}
 public static void Run(){try{
 EditorSceneManager.OpenScene("Assets/Scenes/Level1Rooms.unity");var level=UnityEngine.Object.FindAnyObjectByType<FirstLevelRooms>();for(int i=0;i<level.rooms.Length;i++)level.rooms[i].SetActive(i==0);level.pausePanel.SetActive(false);
 var fx=level.gameObject.AddComponent<FirstRoomTankEffects>();Require(fx.Initialize(level),"First room rejected");fx.enabled=false;fx.Tick(1);Require(fx.VisibleDust==40,"Idle room has no ambient dust");var motes=level.rooms[0].GetComponentsInChildren<SpriteRenderer>().Where(s=>s.name.StartsWith("Sunlit Room Dust")).ToArray();var positions=motes.Select(s=>s.transform.position).ToArray();level.player.position+=Vector3.right;fx.Tick(0);for(int i=0;i<motes.Length;i++)Require(Vector3.Distance(positions[i],motes[i].transform.position)<.001f,"Dust follows tank");Require(Vector2.Distance(fx.Shadow.transform.position,(Vector2)level.player.position+new Vector2(-.18f,-.22f))<.001f,"Shadow fails to follow hero");Require(fx.Shadow.color.a>=.4f && fx.Shadow.GetComponent<Collider2D>()==null,"Shadow too faint or physical");Require(level.rooms[0].GetComponentsInChildren<SpriteRenderer>().Any(s=>s.name.StartsWith("Tank Contact Shadow") && s.sprite==level.player.GetComponent<SpriteRenderer>().sprite),"Missing tank silhouette shadow");
 float alpha=motes[0].color.a;var pos=motes[0].transform.position;level.pausePanel.SetActive(true);fx.Tick(1);Require(Mathf.Approximately(alpha,motes[0].color.a) && pos==motes[0].transform.position,"Paused dust moves");level.pausePanel.SetActive(false);fx.Tick(1);Require(pos!=motes[0].transform.position && !Mathf.Approximately(alpha,motes[0].color.a),"Ambient dust does not drift/fade");for(int i=0;i<1000;i++)fx.Tick(.016f);Require(fx.VisibleDust==40,"Ambient objects accumulate/disappear");
 var show=typeof(FirstLevelRooms).GetMethod("ShowRoom",BindingFlags.NonPublic|BindingFlags.Instance);foreach(int room in new[]{1,2}){show.Invoke(level,new object[]{room});fx.Tick(0);Require(!fx.Shadow.gameObject.activeSelf && fx.VisibleDust==0,"Effects leak into other room");}show.Invoke(level,new object[]{0});fx.Tick(0);Require(fx.Shadow.gameObject.activeSelf && fx.VisibleDust==40,"Returning fails to restore effects");
 foreach(var name in new[]{"level2","level3"}){EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");level=UnityEngine.Object.FindAnyObjectByType<FirstLevelRooms>();fx=level.gameObject.AddComponent<FirstRoomTankEffects>();Require(!fx.Initialize(level),"Effects leak into "+name);}
 File.WriteAllText("Tools/first-room-effects-result.txt","PASSED: room 1.1 ambient dust visible while tank is idle; dust independent of tank movement; particles drift and fade; pause freezes particles; shadow follows tank with visible opacity and native silhouette; exactly 40 dust sprites; other rooms and levels excluded.");
 }catch(Exception e){File.WriteAllText("Tools/first-room-effects-result.txt","FAILED: "+e);throw;}}
}
